}

Method.Source:
/// <summary>
/// ShipmentId parameter
/// </summary>
/// <param name = "_shipmentId">shipmentId</param>
/// <returns>shipmentId</returns>
[
    DataMemberAttribute("@MET:METSalesShipmentId"),
    SysOperationLabelAttribute(literalStr("@MET:ContinuousPermissionNotice")),
    SysOperationControlVisibilityAttribute(false)

]
public RecId parmshipmentId(RecId _shipmentId = shipmentId)
{
    shipmentId = _shipmentId;
    return shipmentId;
}
